private static final String TAG="HiddenApiRegistry"; private static HiddenApiRegistry sInstance; private static final Map<String,Object> VALUES=new HashMap<>();
private HiddenApiRegistry(){}
public static synchronized HiddenApiRegistry get(){if(sInstance==null)sInstance=new HiddenApiRegistry();return sInstance;}
public Object service(String name){if(VALUES.containsKey(name))return VALUES.get(name);try{Class<?> type=Class.forName("android.os.ServiceManager");Method method=type.getDeclaredMethod("getService",String.class);method.setAccessible(true);Object value=method.invoke(null,name);VALUES.put(name,value);return value;}catch(Throwable failure){Log.w(TAG,"service missing "+name,failure);return null;}}
public Object call(Object target,String name,Object...args){if(target==null)return null;try{for(Method method:target.getClass().getDeclaredMethods()){if(method.getName().equals(name)&&method.getParameterTypes().length==args.length){method.setAccessible(true);return method.invoke(target,args);}}}catch(Throwable ignored){}return null;}
